def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 100:
        return 'D'

    my_last, opp_last = history[-1]
    opp_def = sum(1 for _, o in history if o == 'D')
    my_def = sum(1 for m, _ in history if m == 'D')

    # Probe at round 50 if opponent has never defected and we haven't either
    if n == 50 and opp_def == 0 and my_def == 0:
        return 'D'

    # Exploit a never-defecting opponent after we've probed
    if opp_def == 0 and my_def > 0 and n > 50:
        if my_def == 1 and my_last == 'D':
            return 'C'
        return 'D'

    # Forgiving Tit-for-Tat
    if opp_last == 'D':
        if opp_def <= max(1, n // 10):
            return 'C'
        if my_last == 'D' and opp_def <= n // 2:
            return 'C'
        return 'D'
    else:
        if n >= 3:
            recent_my = [m for m, _ in history[-3:]]
            recent_opp = [o for _, o in history[-3:]]
            if all(m == 'D' for m in recent_my) and all(o == 'C' for o in recent_opp):
                return 'D'
        if n > 90:
            diff = 0
            for m, o in history:
                if m == 'D' and o == 'C':
                    diff += 5
                elif m == 'C' and o == 'D':
                    diff -= 5
            if diff < 0:
                return 'D'
        return 'C'
